{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "Using EFPA Parts A–C, the description identifies content, scoring and a narrow intended use. Reinterpreting test takers as AI systems and reliability as repeated-evaluation precision, sections 9.3/9.7 lack evidence; section 9.8 warrants 0 (insufficient information), not 1 (inadequate). Other documentation, materials, norms, validity, fair-use and report qualities remain unassessed. Human sensory, disability and debriefing questions are inapplicable literally.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither documented nor explicitly excluded."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One score cannot establish consistency across runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "EFPA Part A describes a narrowly scoped grid-performance instrument. For sections 9.3/9.7, repeated-evaluation precision replaces human retest stability. Explicitly conducting only one run leaves precision unestablished, supporting 9.8 = 0 rather than evidence of inadequate stability. Other EFPA domains lack sufficient evidence for evaluation. Human sensory prerequisites, disability accommodations and participant feedback are literally inapplicable.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly excludes repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "No repeated scores establish stability or instability."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "EFPA sections 9.3/9.7 are reinterpreted as consistency of AI evaluation under fixed conditions. Repeated scores satisfy the stated stability rule for this comparison. That rule is not an EFPA reliability coefficient or an overall precision rating; broader sampling and generalisation remain unestablished. Part A supplies basic content, scoring and purpose; other EFPA domains remain insufficiently documented. Literal human-testing requirements are inapplicable.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage documents repeated evaluation under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's explicit stability definition."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "Reinterpreting EFPA sections 9.3/9.7 as AI repeated-evaluation precision, the reported variation fails the comparison's explicit stability requirement. This is adverse evidence, distinct from missing reliability evidence. No coefficient-based EFPA rating is inferred from a score range. Content, scoring and narrow purpose are described; other EFPA domains remain insufficiently evidenced. Human sensory, disability and debriefing questions are literally inapplicable.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under unchanged conditions is explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The reported range exceeds the explicitly permitted two percentage points."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "EFPA sections 6.3.8 and 5 distinguish installation guidance from technical measurement evidence. Installation instructions provide some procedural information but do not establish sections 9.3/9.7 repeated-evaluation precision; 9.8 remains 0 for insufficient information. AI systems replace human test takers; literal human accessibility and debriefing questions are inapplicable. Other documentation, materials, norms, validity, fair-use and report qualities remain unassessed.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no repeated-score evidence."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "EFPA Part A identifies a narrow intended comparison, with AI systems replacing human test takers. Sections 6 and 10 distinguish observed grid performance from validity for broader interpretations: the reported comparison supports the stated use but supplies no cross-domain validation. Reliability, norms, materials, fair use and generated reports remain insufficiently evidenced or applicability undetermined. Literal human demographic, sensory and feedback questions are inapplicable.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher score on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "Under EFPA sections 6 and 10, the intended cross-domain selection requires validity evidence beyond the observed grid comparison. Reinterpreting examinees as AI systems, the passage supports the narrow result while leaving the claimed broader use unvalidated; missing evidence does not establish that the opposite ranking is true. Other EFPA domains remain insufficiently evidenced. Literal human demographic, sensory and debriefing questions are inapplicable.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence validating that use."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "EFPA sections 10.3.1.6 and 10.3.2 distinguish initial scores from later evidence linking assistance to workshop correctness. Random allocation, blinded checking and reported uncertainty support the local intended use, without establishing safety or wider generalisation. AI assistance is the evaluation target; inspectors are described trial actors, not participants in this review experiment. Human examinee-specific questions are not directly applicable. Other EFPA domains remain insufficiently documented.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Initial scores alone supply no demonstrated relationship to real workshop decision improvement."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial reports higher correctness with A and an interval favouring A within the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish improvement in an unmeasured safety outcome."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. EFPA's full framework informed these focused reviews; claim labels are separate from EFPA ratings. Unreported evidence was not treated as demonstrated poor quality. No aggregate benchmark-quality score was calculated. Source: EFPA Test Review Model 5.0 (2025), supplied extraction, CC BY-SA 4.0, https://www.efpa.eu/; no external sources consulted."
}
